<script setup lang="ts">import{onMounted,ref}from'vue';import{ElMessage,type TagProps}from'element-plus';import{api,type ApiResponse,type ShopOrder,type OrderStatus}from'@whaashop/shared';interface Page<T>{items:T[];total:number}const rows=ref<ShopOrder[]>([]),status=ref<OrderStatus|''>(''),page=ref(1),size=ref(20),total=ref(0);const statusMap:Record<OrderStatus,{label:string;type:TagProps['type']}>= {PENDING_PAYMENT:{label:'待支付',type:'warning'},PAID:{label:'已支付，待发货',type:'primary'},SHIPPED:{label:'已发货，待收货',type:'info'},COMPLETED:{label:'已完成',type:'success'},CLOSED:{label:'已关闭',type:'danger'}};async function load(){const{data}=await api.get<ApiResponse<Page<ShopOrder>>>('/admin/orders',{params:{status:status.value||undefined,page:page.value,size:size.value}});rows.value=data.data.items;total.value=data.data.total}function filter(){page.value=1;load()}async function ship(id:number){await api.post(`/admin/orders/${id}/ship`);ElMessage.success('虚拟发货成功');load()}onMounted(load)</script>
<template><div class="panel"><div class="toolbar"><h2>订单管理</h2><el-select v-model="status" clearable placeholder="全部状态" style="width:190px" @change="filter"><el-option label="待支付" value="PENDING_PAYMENT"/><el-option label="已支付，待发货" value="PAID"/><el-option label="已发货，待收货" value="SHIPPED"/><el-option label="已完成" value="COMPLETED"/><el-option label="已关闭" value="CLOSED"/></el-select></div><el-table :data="rows"><el-table-column prop="orderNo" label="订单号" min-width="180"/><el-table-column prop="userId" label="用户ID"/><el-table-column label="金额"><template #default="s">¥{{s.row.totalAmount}}</template></el-table-column><el-table-column label="订单状态" width="150"><template #default="s"><el-tag :type="statusMap[s.row.status as OrderStatus]?.type||'info'">{{statusMap[s.row.status as OrderStatus]?.label||'未知状态'}}</el-tag></template></el-table-column><el-table-column prop="receiverName" label="收货人"/><el-table-column prop="createdAt" label="创建时间" width="190"/><el-table-column label="操作"><template #default="s"><el-button v-if="s.row.status==='PAID'" type="primary" size="small" @click="ship(s.row.id)">虚拟发货</el-button><span v-else>—</span></template></el-table-column></el-table><el-empty v-if="!rows.length" description="暂无订单"/><el-pagination v-model:current-page="page" v-model:page-size="size" :total="total" :page-sizes="[10,20,50]" layout="total, sizes, prev, pager, next, jumper" style="margin-top:18px;justify-content:flex-end" @current-change="load" @size-change="filter"/></div></template>
